fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // The problem guarantees that `sep` is non-empty.
    assert!(!sep.is_empty(), "Separator must be non-empty");

    let mut result = Vec::with_capacity(a.len());
    for s in a {
        if maxsplit == 0 {
            // No splitting requested; return the original string as the sole element.
            result.push(vec![s]);
        } else {
            // Perform at most maxsplit splits from the right, yielding at most maxsplit + 1 parts.
            let mut parts: Vec<String> = s
                .rsplitn((maxsplit as usize) + 1, sep.as_str())
                .map(|substr| substr.to_string())
                .collect();
            // rsplitn yields parts in right-to-left order; reverse to restore left-to-right.
            parts.reverse();
            result.push(parts);
        }
    }
    result
}